content:
:root {
  --color-bg-primary: #0f172a;
  --color-bg-surface: #1e293b;
  --color-bg-surface-elevated: #334155;
  --color-text-main: #f8fafc;
  --color-text-muted: #94a3b8;
  --color-accent-green: #10b981;
  --color-accent-green-glow: rgba(16, 185, 129, 0.4);
  --color-accent-amber: #f59e0b;
  --color-accent-red: #ef4444;
  --color-accent-cyan: #06b6d4;
  --color-border: #475569;
  --font-family-base: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-family-display: "Courier New", Courier, monospace, "Segoe UI", sans-serif;
  --shadow-card: 0 10px 25px -5px rgba(0, 0, 0, 0.4), 0 8px 10px -6px rgba(0, 0, 0, 0.4);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-full: 9999px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: var(--font-family-base);
  background-color: var(--color-bg-primary);
  color: var(--color-text-main);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 16px 8px;
  overflow-x: hidden;
  user-select: none;
  -webkit-user-select: none;
}

/* アプリ全体コンテナ */
.snake-app {
  width: 100%;
  max-width: 520px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

/* ヘッダーエリア */
.game-header {
  width: 100%;
  text-align: center;
  padding: 4px 0;
}

.game-title {
  font-size: 1.85rem;
  font-weight: 900;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: #a7f3d0;
  text-shadow: 0 0 12px var(--color-accent-green-glow), 0 2px 4px rgba(0, 0, 0, 0.8);
  margin-bottom: 2px;
}

/* スコアボード */
.scoreboard-card {
  width: 100%;
  background: linear-gradient(135deg, rgba(30, 41, 59, 0.95), rgba(15, 23, 42, 0.95));
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  box-shadow: var(--shadow-card);
}

.score-item {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  background-color: rgba(15, 23, 42, 0.6);
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  border: 1px solid rgba(71, 85, 105, 0.4);
}

.score-label {
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.score-value {
  font-family: var(--font-family-display);
  font-size: 1.4rem;
  font-weight: 800;
  color: #34d399;
  text-shadow: 0 0 8px rgba(52, 211, 153, 0.4);
}

/* 難易度切り替えセレクター */
.difficulty-selector {
  display: flex;
  gap: 8px;
  justify-content: center;
  width: 100%;
}

.diff-btn {
  flex: 1;
  background-color: var(--color-bg-surface-elevated);
  border: 1px solid var(--color-border);
  color: var(--color-text-muted);
  font-size: 0.8rem;
  font-weight: 700;
  padding: 6px 8px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.2s ease;
  text-transform: uppercase;
}

.diff-btn:hover {
  background-color: #475569;
  color: var(--color-text-main);
}

.diff-btn-active {
  background-color: var(--color-accent-green);
  color: #022c22;
  border-color: #059669;
  font-weight: 800;
  box-shadow: 0 0 10px var(--color-accent-green-glow);
}

/* ゲーム盤面コンテナ */
.board-container {
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
}

.game-canvas-wrapper {
  position: relative;
  width: 100%;
  max-width: 440px;
  aspect-ratio: 1 / 1;
  background-color: #090d16;
  border: 2px solid var(--color-border);
  border-radius: var(--radius-md);
  box-shadow: inset 0 0 20px rgba(0, 0, 0, 0.9), var(--shadow-card);
  overflow: hidden;
  display: flex;
  justify-content: center;
  align-items: center;
}

.game-canvas {
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
}

/* 盤面上のオーバーレイ（ゲームオーバー／ポーズ／待機） */
.game-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(15, 23, 42, 0.85);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 24px;
  gap: 12px;
  z-index: 10;
  text-align: center;
  animation: fadeIn 0.2s ease-out;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

.overlay-title {
  font-size: 2rem;
  font-weight: 900;
  color: #f1f5f9;
  letter-spacing: 0.05em;
  text-shadow: 0 0 12px rgba(255, 255, 255, 0.3);
}

.overlay-subtitle {
  font-size: 1rem;
  color: var(--color-text-muted);
  line-height: 1.4;
  margin-bottom: 8px;
}

/* アクションボタン（共通） */
.btn-action {
  font-family: inherit;
  font-size: 0.95rem;
  font-weight: 700;
  padding: 10px 20px;
  border-radius: var(--radius-sm);
  border: none;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  transition: all 0.15s ease;
  touch-action: manipulation;
}

.btn-action:active {
  transform: scale(0.96);
}

.btn-primary {
  background-color: var(--color-accent-green);
  color: #022c22;
  box-shadow: 0 4px 12px var(--color-accent-green-glow);
}

.btn-primary:hover {
  background-color: #34d399;
}

.btn-secondary {
  background-color: var(--color-bg-surface-elevated);
  color: var(--color-text-main);
  border: 1px solid var(--color-border);
}

.btn-secondary:hover {
  background-color: #475569;
}

/* コントローラー全体 */
.controls-container {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  margin-top: 4px;
}

/* 十字ボタン (D-Pad) レイアウト */
.dpad-grid {
  display: grid;
  grid-template-columns: repeat(3, 62px);
  grid-template-rows: repeat(3, 62px);
  gap: 8px;
  justify-content: center;
  align-items: center;
}

.dpad-btn {
  background: linear-gradient(145deg, #1e293b, #0f172a);
  border: 1px solid var(--color-border);
  color: #e2e8f0;
  font-size: 1.4rem;
  font-weight: 900;
  border-radius: var(--radius-md);
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  touch-action: manipulation;
  user-select: none;
  -webkit-user-select: none;
  transition: all 0.1s ease;
  width: 100%;
  height: 100%;
}

.dpad-btn:active {
  background: var(--color-accent-green);
  color: #022c22;
  transform: translateY(2px) scale(0.95);
  box-shadow: 0 0 10px var(--color-accent-green-glow);
}

.dpad-up {
  grid-column: 2;
  grid-row: 1;
}

.dpad-left {
  grid-column: 1;
  grid-row: 2;
}

.dpad-down {
  grid-column: 2;
  grid-row: 3;
}

.dpad-right {
  grid-column: 3;
  grid-row: 2;
}

/* 補助ボタン（ポーズ・リセットなど） */
.utility-buttons {
  display: flex;
  gap: 12px;
  width: 100%;
  justify-content: center;
}

.utility-buttons .btn-action {
  flex: 1;
  max-width: 160px;
}

/* 操作説明カード */
.instructions-card {
  width: 100%;
  background-color: rgba(30, 41, 59, 0.6);
  border: 1px solid rgba(71, 85, 105, 0.5);
  border-radius: var(--radius-sm);
  padding: 10px 14px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.instruction-text {
  font-size: 0.78rem;
  color: var(--color-text-muted);
  line-height: 1.4;
  text-align: center;
}

/* スマートフォンおよび狭い画面向け最適化 */
@media (max-width: 440px) {
  .snake-app {
    gap: 12px;
  }

  .game-title {
    font-size: 1.5rem;
  }

  .dpad-grid {
    grid-template-columns: repeat(3, 56px);
    grid-template-rows: repeat(3, 56px);
    gap: 6px;
  }

  .score-value {
    font-size: 1.25rem;
  }

  .btn-action {
    padding: 8px 14px;
    font-size: 0.9rem;
  }
}

export type Direction = 'UP' | 'DOWN' | 'LEFT' | 'RIGHT';

export interface Point {
  x: number;
  y: number;
}

export type GameStatus = 'IDLE' | 'PLAYING' | 'PAUSED' | 'GAME_OVER';

export type DifficultyLevel = 'EASY' | 'NORMAL' | 'HARD';

export interface GameStats {
  score: number;
  highScore: number;
  length: number;
}

export interface GameControlsProps {
  onDirectionChange: (dir: Direction) => void;
  onTogglePause: () => void;
  onRestart: () => void;
  gameStatus: GameStatus;
}

export interface GameBoardProps {
  snake: Point[];
  food: Point;
  boardSize: number;
  gameStatus: GameStatus;
  onRestart: () => void;
}

export interface ScoreBoardProps {
  score: number;
  highScore: number;
  level: DifficultyLevel;
  onSelectLevel: (lvl: DifficultyLevel) => void;
  gameStatus: GameStatus;
}

import { FC } from 'react';
import { DifficultyLevel, ScoreBoardProps } from '../types';

const LEVEL_LABELS: Record<DifficultyLevel, string> = {
  EASY: '初級',
  NORMAL: '中級',
  HARD: '上級',
};

const ScoreBoard: FC<ScoreBoardProps> = ({
  score = 0,
  highScore = 0,
  level = 'NORMAL',
  onSelectLevel,
  gameStatus = 'IDLE',
}) => {
  const levels: DifficultyLevel[] = ['EASY', 'NORMAL', 'HARD'];

  const handleDifficultyClick = (lvl: DifficultyLevel) => {
    if (gameStatus === 'PLAYING') {
      return;
    }
    onSelectLevel?.(lvl);
  };

  return (
    <div className="scoreboard-card">
      <div className="score-item">
        <span className="score-label">スコア</span>
        <span className="score-value">{score}</span>
      </div>

      <div className="score-item">
        <span className="score-label">ハイスコア</span>
        <span className="score-value">{highScore}</span>
      </div>

      <div className="difficulty-selector">
        {levels.map((lvl) => {
          const isActive = level === lvl;
          return (
            <button
              key={lvl}
              type="button"
              className={`diff-btn ${isActive ? 'diff-btn-active' : ''}`}
              onClick={() => handleDifficultyClick(lvl)}
              disabled={gameStatus === 'PLAYING'}
              title={gameStatus === 'PLAYING' ? 'プレイ中は難易度を変更できません' : `${LEVEL_LABELS[lvl]}に変更`}
            >
              {LEVEL_LABELS[lvl]}
            </button>
          );
        })}
      </div>
    </div>
  );
};

export default ScoreBoard;

import { FC, useEffect, useRef } from 'react';
import { GameBoardProps } from '../types';

const GameBoard: FC<GameBoardProps> = ({
  snake = [],
  food = { x: 5, y: 5 },
  boardSize = 20,
  gameStatus = 'IDLE',
  onRestart,
}) => {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  // Canvas描画
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const logicalSize = 400;
    const cellSize = logicalSize / boardSize;

    // 背景クリア
    ctx.fillStyle = '#090d16';
    ctx.fillRect(0, 0, logicalSize, logicalSize);

    // 微細なグリッド線を描画
    ctx.strokeStyle = '#1e293b';
    ctx.lineWidth = 1;
    for (let i = 0; i <= boardSize; i++) {
      const pos = i * cellSize;
      ctx.beginPath();
      ctx.moveTo(pos, 0);
      ctx.lineTo(pos, logicalSize);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(0, pos);
      ctx.lineTo(logicalSize, pos);
      ctx.stroke();
    }

    // 餌の描画（光る赤いリンゴ風）
    const foodCenterX = food.x * cellSize + cellSize / 2;
    const foodCenterY = food.y * cellSize + cellSize / 2;
    const foodRadius = cellSize * 0.4;

    ctx.save();
    ctx.shadowColor = '#ef4444';
    ctx.shadowBlur = 12;
    ctx.fillStyle = '#ef4444';
    ctx.beginPath();
    ctx.arc(foodCenterX, foodCenterY, foodRadius, 0, Math.PI * 2);
    ctx.fill();

    // 餌のハイライト
    ctx.fillStyle = '#fca5a5';
    ctx.beginPath();
    ctx.arc(foodCenterX - foodRadius * 0.3, foodCenterY - foodRadius * 0.3, foodRadius * 0.35, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    // 蛇の描画
    snake.forEach((part, index) => {
      const isHead = index === 0;
      const x = part.x * cellSize;
      const y = part.y * cellSize;
      const padding = 1.5;
      const partSize = cellSize - padding * 2;
      const radius = isHead ? 6 : 4;

      ctx.save();
      if (isHead) {
        ctx.fillStyle = '#34d399';
        ctx.shadowColor = '#10b981';
        ctx.shadowBlur = 10;
      } else {
        // 体は後方ほど少しトーンを落とす
        const ratio = Math.max(0.4, 1 - index / (snake.length + 5));
        ctx.fillStyle = `rgba(16, 185, 129, ${ratio})`;
      }

      // 丸みを帯びた四角形を描画
      ctx.beginPath();
      ctx.roundRect(x + padding, y + padding, partSize, partSize, radius);
      ctx.fill();

      // 頭部には目をつける
      if (isHead) {
        ctx.fillStyle = '#022c22';
        const eyeOffset = cellSize * 0.28;
        const eyeRadius = cellSize * 0.1;

        // 次の体節との相対位置から進行方向を簡易推測
        const nextPart = snake[1];
        let dx = 0;
        let dy = -1;
        if (nextPart) {
          dx = part.x - nextPart.x;
          dy = part.y - nextPart.y;
        }

        let eye1X = foodCenterX;
        let eye1Y = foodCenterY;
        let eye2X = foodCenterX;
        let eye2Y = foodCenterY;

        const centerX = x + cellSize / 2;
        const centerY = y + cellSize / 2;

        if (dx === 1) {
          // 右向き
          eye1X = centerX + eyeOffset;
          eye1Y = centerY - eyeOffset;
          eye2X = centerX + eyeOffset;
          eye2Y = centerY + eyeOffset;
        } else if (dx === -1) {
          // 左向き
          eye1X = centerX - eyeOffset;
          eye1Y = centerY - eyeOffset;
          eye2X = centerX - eyeOffset;
          eye2Y = centerY + eyeOffset;
        } else if (dy === 1) {
          // 下向き
          eye1X = centerX - eyeOffset;
          eye1Y = centerY + eyeOffset;
          eye2X = centerX + eyeOffset;
          eye2Y = centerY + eyeOffset;
        } else {
          // 上向き
          eye1X = centerX - eyeOffset;
          eye1Y = centerY - eyeOffset;
          eye2X = centerX + eyeOffset;
          eye2Y = centerY - eyeOffset;
        }

        ctx.beginPath();
        ctx.arc(eye1X, eye1Y, eyeRadius, 0, Math.PI * 2);
        ctx.arc(eye2X, eye2Y, eyeRadius, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();
    });
  }, [snake, food, boardSize]);

  return (
    <div className="board-container">
      <div className="game-canvas-wrapper">
        <canvas
          ref={canvasRef}
          width={400}
          height={400}
          className="game-canvas"
        />

        {gameStatus === 'IDLE' && (
          <div className="game-overlay">
            <h2 className="overlay-title">スネークゲーム</h2>
            <p className="overlay-subtitle">
              十字ボタンまたはキーボードで蛇を操作して餌を食べよう！
            </p>
            <button
              type="button"
              className="btn-action btn-primary"
              onClick={() => onRestart?.()}
            >
              ゲーム開始
            </button>
          </div>
        )}

        {gameStatus === 'PAUSED' && (
          <div className="game-overlay">
            <h2 className="overlay-title">一時停止中</h2>
            <p className="overlay-subtitle">
              再開ボタンを押すか、スペースキーでゲームに戻ります
            </p>
            <button
              type="button"
              className="btn-action btn-primary"
              onClick={() => onRestart?.()}
            >
              再開する
            </button>
          </div>
        )}

        {gameStatus === 'GAME_OVER' && (
          <div className="game-overlay">
            <h2 className="overlay-title">ゲームオーバー</h2>
            <p className="overlay-subtitle">壁や自分の体に衝突しました！</p>
            <button
              type="button"
              className="btn-action btn-primary"
              onClick={() => onRestart?.()}
            >
              もう一度遊ぶ
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default GameBoard;

import { FC, PointerEvent } from 'react';
import { Direction, GameControlsProps } from '../types';

const Controls: FC<GameControlsProps> = ({
  onDirectionChange,
  onTogglePause,
  onRestart,
  gameStatus = 'IDLE',
}) => {
  const handleDirectionPress = (dir: Direction, e: PointerEvent<HTMLButtonElement>) => {
    e.preventDefault();
    onDirectionChange?.(dir);
  };

  const isPlaying = gameStatus === 'PLAYING';
  const isPaused = gameStatus === 'PAUSED';

  return (
    <div className="controls-container">
      {/* 十字方向キーパッド */}
      <div className="dpad-grid" role="group" aria-label="方向ボタン">
        <button
          type="button"
          aria-label="上へ移動"
          className="dpad-btn dpad-up"
          onPointerDown={(e) => handleDirectionPress('UP', e)}
        >
          ▲
        </button>
        <button
          type="button"
          aria-label="左へ移動"
          className="dpad-btn dpad-left"
          onPointerDown={(e) => handleDirectionPress('LEFT', e)}
        >
          ◀
        </button>
        <button
          type="button"
          aria-label="右へ移動"
          className="dpad-btn dpad-right"
          onPointerDown={(e) => handleDirectionPress('RIGHT', e)}
        >
          ▶
        </button>
        <button
          type="button"
          aria-label="下へ移動"
          className="dpad-btn dpad-down"
          onPointerDown={(e) => handleDirectionPress('DOWN', e)}
        >
          ▼
        </button>
      </div>

      {/* 補助操作ボタン（一時停止・リセット） */}
      <div className="utility-buttons">
        <button
          type="button"
          className="btn-action btn-secondary"
          onClick={() => onTogglePause?.()}
          disabled={gameStatus === 'GAME_OVER' || gameStatus === 'IDLE'}
        >
          {isPaused ? '再開' : 'ポーズ'}
        </button>
        <button
          type="button"
          className="btn-action btn-secondary"
          onClick={() => onRestart?.()}
        >
          {isPlaying || isPaused ? 'やり直す' : 'スタート'}
        </button>
      </div>
    </div>
  );
};

export default Controls;
